import * as store from "../runtime/store.js";
import type { Row } from "../runtime/store.js";
import type { Slot, Client, Booking } from "../types.js";

// The step may touch only the tables it declares.
const all = (table: "Booking" | "Slot"): Row[] => store.all(table);
const find = (table: "Booking" | "Slot", id: string): Row | undefined => store.find(table, id);

export async function findBookings(client: Client): Promise<Booking[]> {
  const now = Date.now();
  const results: { booking: Booking; startsAt: number }[] = [];
  for (const row of all("Booking")) {
    const booking = row as Booking;
    if (booking.client_id !== client.id) continue;
    const slot = find("Slot", booking.slot_id) as Slot | undefined;
    if (!slot) continue;
    const startsAt = Date.parse(slot.starts_at);
    if (Number.isNaN(startsAt) || startsAt < now) continue;
    results.push({ booking, startsAt });
  }
  results.sort((a, b) => a.startsAt - b.startsAt);
  return results.map((r) => r.booking);
}
